class Knoten:
    def __init__(self, wert):
        self.wert = wert
        self.next = None

class Stack:
    def __init__(self):
        self.top = None

    def push(self, wert):
        neu = Knoten(wert)
        neu.next = self.top
        self.top = neu

    def pop(self):
        if self.top is None:
            raise IndexError("Stack leer")
        wert = self.top.wert
        self.top = self.top.next
        return wert

    def peek(self):
        if self.top is None:
            raise IndexError("Stack leer")
        return self.top.wert

    def is_empty(self):
        return self.top is None

s = Stack()
s.push(1)
s.push(2)
print(s.pop())       # 2
print(s.peek())      # 1
print(s.is_empty())  # False

def klammern_ok(text):
    paare = {")": "(", "]": "[", "}": "{"}
    stapel = []
    for z in text:
        if z in "([{":
            stapel.append(z)
        elif z in paare:
            if not stapel:
                return False
            if stapel.pop() != paare[z]:
                return False
    return len(stapel) == 0

print(klammern_ok("(a[1] + b) * 2"))  # True
print(klammern_ok("([)]"))   # False
print(klammern_ok("(("))     # False
